mapper.select:
select 
from drive_node
where space_id = #{spaceId}
  and parent_id = #{parentId}
  and status = 'ACTIVE'

select count(1)
from drive_node
where space_id = #{spaceId}
  and parent_id = #{parentId}
  and normalized_name = #{normalizedName}
  and status = 'ACTIVE'
  and active_flag = 1

  and node_id != #{excludeNodeId}

mapper.update:
update drive_node
set parent_id = case when node_id = #{rootNodeId}
                     then #{parentId} else parent_id end,
    ancestors = case when node_id = #{rootNodeId}
                     then #{rootAncestors}
                     else concat(#{newPrefix},
                          substring(ancestors, char_length(#{oldPrefix}) + 1)) end,
    node_name = case when node_id = #{rootNodeId}
                     then #{rootName} else node_name end,
    normalized_name = case when node_id = #{rootNodeId}
                           then #{normalizedName} else normalized_name end,
    status = 'ACTIVE',
    active_flag = 1,
    original_parent_id = null,
    trash_root_id = null,
    trashed_by = null,
    trashed_time = null,
    purge_after = null,
    version = version + 1,
    update_by = #{updateBy},
    update_time = now()
where trash_root_id = #{trashRootId}
  and status = 'TRASHED'
  and (node_id = #{rootNodeId}
       or ancestors = #{oldPrefix}
       or ancestors like concat(#{oldPrefix}, ',%'))

update drive_node
set status = 'PURGING',
    version = version + 1,
    update_by = #{updateBy},
    update_time = now()
where node_id = #{trashRootId}
  and trash_root_id = #{trashRootId}
  and version = #{expectedVersion}
  and status = #{expectedStatus}
  and (#{expectedStatus} != 'PURGING'
       or update_time is null
       or update_time < #{staleBefore})

